full_text:
Привет, Хабр! Меня зовут mixitosik, я разрабатываю открытый язык программирования общего назначения
RayQuiro
.
Когда берешься за создание собственного языка, большинство гайдов и туториалов быстро упираются в тупик: они учат писать либо «игрушечные» древовидные интерпретаторы (Tree-walk AST), либо простые трансляторы в C. На практике же любой язык общего назначения требует решения жестких системных задач: проектирования компонуемой модульной системы, многоуровневого пайплайна исполнения (для мгновенных итераций и для продакшена), кроссплатформенного рантайма и интеграции легковесного GUI без раздувания зависимостей до размеров Electron.
В этой статье я по шагам разберу внутреннее устройство RayQuiro: структуру парсера и AST, архитектуру стековой виртуальной машины, генерацию IR для LLVM-бэкенда, а также инженерные грабли, на которые пришлось наступить при реализации динамического языка со строгим управлением памятью.
1. Концепция и Зачем: архитектурные уровни RayQuiro
Главная задача RayQuiro — дать выразительный синтаксис с динамической типизацией во время выполнения, но при этом сохранить нулевой порог входа и высокую производительность.
Поэтому среда исполнения разделена на три независимых уровня (Tiered Execution Pipeline):
┌───────────────────────┐
 │ RayQuiro Source │
 │ (*.rq) │
 └──────────┬────────────┘
 │ Lexer / Parser
 ▼
 ┌───────────────────────┐
 │ AST Program │
 └──────────┬────────────┘
 │
 ┌────────────────────────┼────────────────────────┐
 ▼ ▼ ▼
┌──────────────────┐ ┌──────────────────┐ ┌──────────────────┐
│ Tier 1: AST │ │ Tier 2: VM │ │ Tier 3: Native │
│ Interpreter │ │ Bytecode Engine │ │ LLVM / TCC AOT │
├──────────────────┤ ├──────────────────┤ ├──────────────────┤
│ Zero-startup │ │ High-throughput │ │ LLVM IR opt -O3 │
│ Tree-walk │ │ Stack Machine │ │ Bare-metal EXE │
│ Embedded scripts │ │ Hot Reloading │ │ Standalone dist │
└──────────────────┘ └──────────────────┘ └──────────────────┘
Tier 1 (AST Interpreter)
: прямое исполнение узлов AST обходом дерева. Дает минимальный запуск (< 2 мс), используется во встраиваемых сценариях (
rqio_core
) и как эталонная реализация семантики.
Tier 2 (Bytecode VM)
: трансляция AST в компактный линейный байт-код с исполнением на регистрово-стековой виртуальной машине. Оптимален для быстрой разработки, поддерживает бинарные контейнеры (
.rqb
) и hot-reloading (
rqio run --watch
).
Tier 3 (AOT Native Compiler)
: трансляция семантического графа в оптимизированный C++ / LLVM IR. Сборка идет либо через встроенный TinyCC (сверхбыстрые билды за ~10 мс), либо через Clang/LLVM с проходами
-O3
(векторизация, инлайнинг, устранение мертвого кода) для продакшена.
2. Устройство Лексера и Парсера: от потока символов к AST
Компилятор RayQuiro написан на C++20. Пайплайн обработки текста начинается с лексического анализатора (
Lexer.h
), который переводит поток UTF-8 символов в типизированные токены
Token
.
Лексер: контекстные токены и операторы
Лексер распознает стандартный набор ключевых слов (
fn
,
var
,
let
,
struct
,
match
,
try
,
catch
,
finally
,
throw
,
async
,
await
), составные присваивания (
+=
,
-=
,
*=
,
/=
) и операторы безопасной навигации (
?.
— optional chaining,
??
— null coalescing,
...
— variadic parameter):
C++
enum class TokenType {
 IDENTIFIER, NUMBER, STRING,
 VAR, LET, CONST, FN, STRUCT, ENUM, INTERFACE,
 IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE,
 TRY, CATCH, FINALLY, THROW, MATCH,
 QUESTION_DOT, // ?.
 QUESTION_QUESTION, // ??
 DOT_DOT_DOT, // ...
 ARROW, // =>
 // ...
};
Для операторов
?
,
?.
и
??
в лексере задействован предиктивный просмотр на один символ вперед (
peekNext()
):
C++
if (c == '?' && peekNext() == '?') {
 advance(); advance();
 addToken(tokens, TokenType::QUESTION_QUESTION, "??", startLine, startCol);
 continue;
}
if (c == '?' && peekNext() == '.') {
 advance(); advance();
 addToken(tokens, TokenType::QUESTION_DOT, "?.", startLine, startCol);
 continue;
}
Парсер: рекурсивный спуск и приоритеты операций
Парсер (
Parser.h
) строит абстрактное синтаксическое дерево (AST) методом рекурсивного спуска (Recursive Descent) с учетом приоритетов бинарных операций (Precedence Climbing):
Assignment (=, +=, -=)
 └── Null Coalescing (??)
 └── Logical OR (||)
 └── Logical AND (&&)
 └── Equality (==, !=)
 └── Comparison (<, <=, >, >=)
 └── Term (+, -)
 └── Factor (*, /, %)
 └── Unary (!, -)
 └── Postfix (.field, [index], ?., (args))
 └── Primary (literal, ident, grouping)
Каждый узел выражения наследуется от базовой структуры
Expr
, а оператор — от
Stmt
:
C++
struct Expr {
 virtual ~Expr() = default;
};

struct Stmt {
 virtual ~Stmt() = default;
};

struct NullCoalesceExpr : Expr {
 std::unique_ptr<Expr> left;
 std::unique_ptr<Expr> right;
};

struct OptionalChainExpr : Expr {
 std::unique_ptr<Expr> object;
 std::string field;
 std::unique_ptr<Expr> index;
};

struct ReturnStmt : Stmt {
 std::vector<std::unique_ptr<Expr>> values;
};
Парсер из коробки поддерживает множественные возвращаемые значения и деструктуризацию. При вызове
return a, b, c;
все выражения упаковываются в вектор
values
структуры
ReturnStmt
:
C++
std::unique_ptr<Stmt> parseReturn() {
 auto node = std::make_unique<ReturnStmt>();
 if (!check(TokenType::SEMICOLON) && !check(TokenType::RBRACE) && !isAtEnd()) {
 node->values.push_back(parseAssignment());
 while (match({TokenType::COMMA})) {
 node->values.push_back(parseAssignment());
 }
 }
 match({TokenType::SEMICOLON});
 return node;
}
3. Виртуальная Машина (Bytecode VM): модель данных, стек и опкоды
Виртуальная машина RayQuiro спроектирована по классической стековой модели с плоским представлением инструкций и локальных фреймов.
Универсальное значение: VMValue
Для представления динамических данных используется структура
VMValue
поверх
std::variant
:
C++
struct VMValue {
 using Array = std::vector<VMValue>;
 using Object = std::map<std::string, VMValue>;

 std::variant<std::monostate, double, std::string, bool, Array, Object> data;

 VMValue() : data(std::monostate{}) {}
 VMValue(double value) : data(value) {}
 VMValue(const std::string& value) : data(value) {}
 VMValue(bool value) : data(value) {}
 VMValue(const Array& value) : data(value) {}
 VMValue(const Object& value) : data(value) {}
};
std::monostate
заменяет
null
. Числовые значения хранятся как IEEE 754 64-bit float (
double
), что избавляет от накладных издержек на жесткое разделение целых и вещественных типов в критическом цикле ВМ.
Набор инструкций (Instruction Set Architecture)
Каждая инструкция фиксирована по размеру и содержит опкод плюс два 32-битных аргумента:
C++
struct Instruction {
 OpCode op = OpCode::Return;
 std::int32_t a = 0;
 std::int32_t b = 0;
};
Система команд разбита на группы:
Категория
Опкоды
Описание
Стек и литералы
Constant
,
Null
,
True
,
False
,
Pop
,
Dup
Загрузка констант, дублирование и сброс верхушки стека.
Память
GetLocal
,
SetLocal
,
GetGlobal
,
SetGlobal
Чтение и запись в локальные слоты стекового кадра или глобальный хэш-мап.
Коллекции
BuildArray
,
BuildObject
,
GetIndex
,
SetIndex
Создание контейнеров и доступ по индексу.
Арифметика
Add
,
Subtract
,
Multiply
,
Divide
,
Modulo
,
Negate
Базовые математические операции с приведением типов.
Сравнение и логика
Equal
,
NotEqual
,
Less
,
LessEqual
,
Greater
,
Not
Предикаты и логические инверсии.
Поток управления
Jump
,
JumpIfFalse
,
Loop
,
Call
,
Return
Переходы со смещением указателя инструкций (
ip
).
Исключения
TryBegin
,
TryEnd
,
Throw
Регистрация обработчиков и раскрутка стека.
Байт-код компилятор: разрешение слотов переменных
BytecodeCompiler
транслирует AST в
BytecodeProgram
. Локальные переменные разрешаются на этапе компиляции в фиксированные индексы слотов стека (
GetLocal a
,
SetLocal a
), полностью исключая поиск имен по строкам во время исполнения функций:
C++
int resolveLocal(const std::string& name) {
 for (auto it = scopes_.rbegin(); it != scopes_.rend(); ++it) {
 auto found = it->locals.find(name);
 if (found != it->locals.end()) return found->second;
 }
 return -1; // Не локальная переменная -> поиск в глобалях
}
Цикл диспетчеризации (Dispatch Loop)
Исполнение функций инкапсулировано в
VM::executeFunction
. Стек вызовов управляется через
CallFrame
:
C++
struct CallFrame {
 const BytecodeFunction* function = nullptr;
 std::size_t ip = 0;
 std::size_t stackOffset = 0;
};
Основной цикл интерпретатора использует классический switch-case по опкодам:
C++
while (frame->ip < frame->function->code.size()) {
 const Instruction& inst = frame->function->code[frame->ip++];
 switch (inst.op) {
 case OpCode::Constant:
 push(frame->function->constants[inst.a]);
 break;
 case OpCode::GetLocal:
 push(stack_[frame->stackOffset + inst.a]);
 break;
 case OpCode::SetLocal:
 stack_[frame->stackOffset + inst.a] = peek(0);
 break;
 case OpCode::Add: {
 VMValue b = pop();
 VMValue a = pop();
 if (std::holds_alternative<std::string>(a.data) || std::holds_alternative<std::string>(b.data)) {
 push(VMValue(toString(a) + toString(b)));
 } else {
 push(VMValue(toNumber(a) + toNumber(b)));
 }
 break;
 }
 case OpCode::JumpIfFalse: {
 if (!isTruthy(pop())) {
 frame->ip += inst.a;
 }
 break;
 }
 // ...
 }
}
4. LLVM и TCC AOT-бэкенд: компиляция в машинный код
Для генерации максимального перформанса RayQuiro использует транслятор
Generator.h
и систему компиляции
Compiler.h
.
Стратегия кодогенерации
Вместо динамической диспетчеризации через тяжелый интерпретатор, генератор преобразует AST в семантически эквивалентный код на C++ с прямыми типами
rq::Value
и оптимизированным выделением памяти под структуры. Далее полученный код компилируется:
TinyCC (TCC)
: В состав RayQuiro встроен легкий тулчейн TCC (
tools/tcc/
на Windows или системный пакет на Linux). Это дает сборку в нативный PE/ELF-бинарник за 10–15 миллисекунд без необходимости тащить тяжелые компиляторы вроде MSVC или GCC.
Clang / LLVM Backend (
--release
)
: При флаге
--release
включается тяжелый оптимизирующий пайплайн LLVM:
-O3
оптимизации.
Автоматическая векторизация циклов (Loop Vectorization).
Инлайнинг горячих функций и Dead Code Elimination (DCE).
Проход
mem2reg
для выталкивания локальных переменных из стека памяти прямо на регистры процессора.
Кросс-компиляция
За счет поддержки LLVM Target Triples, кросс-сборка под разные ОС делается одной командой:
Bash
rqio build app.rq --target linux-x64 -o bin/app_linux
rqio build app.rq --target win-x64 -o bin/app.exe
rqio build app.rq --target macos-arm64 -o bin/app_macos
При линковке на Linux компилятор автоматом цепляет системные библиотеки (
-lGL -lm -lpthread -ldl -lrt -lX11
), позволяя собирать десктопные GUI-приложения «из коробки».
5. Примеры кода на RayQuiro
Синтаксис языка проектировался лаконичным, строгим и безопасным в плане работы с
null
.
Объявление структур, функций и деструктуризация
Фрагмент кода
struct Vector2D {
 x: 0,
 y: 0
}

fn divmod(dividend, divisor) {
 if (divisor == 0) {
 throw "Division by zero!";
 }
 var q = floor(dividend / divisor);
 var r = dividend % divisor;
 return q, r;
}

var [quotient, remainder] = divmod(17, 5);
print("Quotient: " + str(quotient) + ", Remainder: " + str(remainder));

var vec = Vector2D { x: 10, y: 25 };
print("Vector point: " + str(vec["x"]) + ", " + str(vec["y"]));
Безопасная навигация и сопоставление с образцом (Pattern Matching)
Фрагмент кода
var config = {
 "network": {
 "port": 8080
 }
};

// Безопасное чтение через optional chaining и null coalescing:
var host = config?.["network"]?.["host"] ?? "127.0.0.1";
var port = config?.["network"]?.["port"] ?? 80;
print("Connecting to: " + host + ":" + str(port));

// Матчинг без проваливания (no fallthrough):
var statusCode = 404;
var statusMessage = "";

match statusCode {
 200 => statusMessage = "OK",
 404 => statusMessage = "Not Found",
 500 => statusMessage = "Internal Server Error",
 _ => statusMessage = "Unknown Status"
}
print("HTTP Status: " + statusMessage);
Разделение app и ui: оконный интерфейс
В RayQuiro разделена логика и стилизация: модуль
app
отвечает за структуру окна и виджеты (DOM), а модуль
ui
— за CSS-подобное оформление:
Фрагмент кода
import "rayquiro.app";
import "rayquiro.ui";

app.init("Системный монитор", 480, 320);

ui.style("background: #18181b; color: #fafafa; font-size: 14;");

var label = app.text("Статус демона: активен");
var check = app.checkbox("Автозапуск при старте", true);
var btn = app.button("Перезагрузить сервис");

btn = ui.apply(btn, {
 "background": "#2563eb",
 "color": "#ffffff",
 "radius": 6,
 "padding": "6px 12px"
});

app.run();
6. Архитектурные вызовы и их решения
При реализации ядра языка пришлось столкнуться с несколькими интересными инженерными задачами.
Вызов 1: Исключения и раскрутка стека в виртуальной машине
Проблема:
В AST-интерпретаторе исключения легко заворачиваются в стандартный C++
try/catch
. Но в байт-код машине нативный C++ механизм дает огромный оверхед, портит локальность кэша инструкций и не дает нормально восстанавливать
ip
(указатель инструкций) вместе с глубиной стека операндов.
Решение:
В ВМ был добавлен отдельный стек контекстов для перехвата исключений:
C++
struct TryHandler {
 std::size_t catchIp;
 std::size_t stackDepth;
 std::string errorParam;
};
std::vector<TryHandler> tryStack_;
Опкод
TryBegin
сохраняет точку возврата
catch
и текущую глубину стека данных. При срабатывании
Throw
машина мгновенно откатывает стек операндов до
stackDepth
, извлекает значение ошибки, прокидывает его в переменную
errorParam
и делает переход на
catchIp
. Если стек
tryStack_
пуст, ошибка подымается на уровень хост-приложения.
Вызов 2: Lvalue-присваивание по вычисляемому индексу
Проблема:
В ряде простых интерпретаторов выражение
table[key] = value
парсится как бинарный оператор
=
, у которого левая часть —
IndexExpr
. Но
IndexExpr
при вычислении возвращает обычное значение (rvalue), полностью теряя ссылку на исходный контейнер и ключ.
Решение:
В AST был выделен специализированный узел
SetIndexExpr
, а в байт-код добавлены точечные инструкции:
SetIndex
для универсальных случаев.
SetLocalIndex
и
SetGlobalIndex
для прямого изменения полей объектов и массивов, лежащих в слотах локальных или глобальных переменных, без лишнего копирования.
Вызов 3: Кроссплатформенная графика без тяжелых зависимостей
Проблема:
Попытка прикрутить к языку десктопный GUI обычно тащит за собой монструозные либы вроде Qt, Electron или GTK, что превращает развертывание под чистой ОС в ад.
Решение:
Для модуля
rayquiro.app
и графической подсистемы мы упаковали кастомизированный Raylib прямо в ядро рантайма. На Linux графический бэкенд общается с X11 и Wayland (через XWayland) по OpenGL, используя встроенные векторные шрифты для рендеринга текста без зависимости от системных шрифтовых демонов.
Заключение
RayQuiro развивается как полностью самостоятельный инструмент, сочетающий удобство скриптового синтаксиса с предсказуемостью нативной компиляции.
Проект открытый, код доступен сообществу:
Репозиторий ядра:
GitHub — RayQuiro
Документация:
rayquiro-docs
Плагин для VS Code:
rayquiro-vscode
Буду рад конструктивной критике в комментариях, обсуждению деталей реализации ВМ и пулл-реквестам!

Находят ли генеративные (рандомизированные) тесты баги заметно лучше, чем юнит-тесты на примерах? На lobste.rs по этому поводу
идёт интересное обсуждение
. Один из доводов в пользу юнит-тестов, если пересказать своими словами, звучит так:
Мой универсальный фаззер не смог найти
вот этот хитрый баг
в Rust-крейте
regex
.
Мне показалось, что генеративное тестирование как раз должно вытряхивать таких зверей, поэтому я написал
небольшой фаззер
сам. И он действительно нашёл в той версии
regex
другой
баг, а потом и тот, за которым я охотился. В последней версии ничего не нашлось. Хочу описать процесс: это хороший учебный пример того, как подступаться к такой задаче.
Сразу оговорюсь: как аргумент это очень слабо. Я точно знаю, какой баг ищу, и даже знаю, что фаззеры способны его найти. Главная цель здесь — научить приёмам, а насколько они эффективны, судите сами. И всё же, по-моему, второй найденный баг подход отчасти подтверждает.
Ещё хочу подчеркнуть, что писать фаззеры под уже известные баги — вовсе не праздная забава. Я считаю, что генеративное тестирование очень мощное относительно своей цены, но всегда остаётся вопрос, достаточно ли тщателен конкретный тест. А он никогда не бывает достаточно тщательным: в другом месте вы
обязательно
найдёте ещё баги (поэтому так важны эшелонированная защита и защитные механизмы во время
выполнения
). И если какой-то вредитель проскочил мимо ваших фаззеров, первым делом считайте это багом в
фаззере
и меняйте его так, чтобы он находил и этот баг, и родственные. Только после этого разрешается добавить исправление и юнит-тест!
Баг
Для регулярного выражения
".abb|b"
и входа
"zabb"
старая версия крейта
regex
возвращала первым совпадением
b
. Это неверно: совпадает вся строка
zabb
.
use regex;

fn main() {
 let r = regex::Regex::new(".abb|b").unwrap();
 let m = r.find("zabb").unwrap();
 // Fails with regex-automata=0.4.15:
 assert_eq!(m.as_str(), "zabb")
}
Как найти этот баг или что-то
похожее
на него?
Движки регулярных выражений — одна из самых удобных целей для генеративного тестирования: это чистые алгоритмы. Большие системы редко состоят
только
из алгоритма, но внутри компонентов интересных систем алгоритмы повсюду, так что это знание прикладное.
Самый важный приём тестирования алгоритмов, с большим отрывом, — сверка с заведомо правильным ответом, с оракулом. Реализуйте алгоритм и за
O(N log N)
, и за
O(N^2)
, и сравнивайте ответы.
Справедливости ради, в исходном комментарии говорилось, что фаззер автора не нашёл проблему именно потому, что у него не было оракула. Но если вы проектируете надёжную систему, обеспечить ей оракул — часть вашей работы! Одним из первых шагов в нашем
Jepsen-тестировании
TigerBeetle было
вынести внутренние временные метки
в API, чтобы Jepsen было проще находить баги (TigerBeetle
проектируется вместе
со своим внутренним симулятором
VOPR
, у которого естественным образом есть доступ к временным меткам и ко всему остальному). А для движка регулярных выражений придумать оракул должно быть несложно: обычно за единым фасадом в них и так живут несколько специализированных реализаций, и их можно сверять друг с другом.
Но случай с
regex
ещё проще, и поэтому он отлично подходит как учебный пример: есть крейт
regex_lite
с тем же API.
Отсюда план: сгенерировать регулярное выражение и входной текст и проверить, что
regex
и
regex_lite
дают одинаковые ответы.
Генерируем строку
Начну с кода, который генерирует случайную строку: он проще, но в нём уже есть пара нетривиальных идей. Для начала нужен генератор случайных чисел:
use fastrand::Rng;
Есть техники и поизощрённее, которые дают
минимизацию тест-кейсов
,
исчерпывающий перебор
или
исследование по покрытию
, но суть в том, что даже скромный ГПСЧ (генератор псевдослучайных чисел) бьёт беспощадно, если правильно им распорядиться.
Когда только начинаешь заниматься рандомизированным тестированием, тянет сгенерировать что-нибудь большое, нет, ОГРОМНОЕ! Уж на 5 ГиБ входных данных
regex
точно подавится? Обычно это неверный ход. Баги,
как правило
, сидят в маленьких, но хитрых примерах, которые сталкивают между собой несколько возможностей. Строка, где все символы одинаковые, скорее вызовет баг, чем совершенно случайная строка, где каждый символ уникален.
Поэтому по умолчанию я генерирую строки так.
Сначала
фиксирую алфавит допустимых символов. Удобный способ его получить — прогнать все юнит-тесты через
sort | unique
. Затем для каждой конкретной строки выбираю
подмножество
этого алфавита. Мне нужны строки, в которых встречаются все символы, но нужны и длинные строки только из
a
и
b
! Потом генерирую строку из выбранного подмножества, причём длину тоже выбираю случайно.
Чтобы фаззинг был эффективным, каждая итерация должна быть как можно быстрее, поэтому память я переиспользую между итерациями — это
статическое выделение памяти
в миниатюре:
use fastrand::Rng;

fn main() {
 let mut rng = Rng::new();

 // Re-use the same memory for all tests.
 let mut text_alphabet: Vec<u8> = vec![];
 let mut text: Vec<u8> = vec![];

 for _ in 0..1_000_000 {
 // It's unlikely that a counter example with
 // 7 different letters exists, while there
 // isn't one with just 6.
 alphabet_swarm(&mut rng, b"abcdef", &mut text_alphabet);
 let text =
 gen_string(&mut rng, &text_alphabet, &mut text);
 }
}

fn alphabet_swarm<'a>(
 rng: &mut Rng,
 all: &[u8],
 pick: &'a mut Vec<u8>,
) {
 pick.clear();
 pick.extend(all);
 rng.shuffle(pick);
 let count = rng.usize(1..=pick.len());
 pick.truncate(count);
}

fn gen_string<'a>(
 rng: &mut Rng,
 alphabet: &[u8],
 result: &'a mut Vec<u8>,
) -> &'a str {
 result.clear();
 // Again, this is a short string.
 // Longer failures are not likely.
 let count = rng.usize(0..8);
 for _ in 0..count {
 result.push(alphabet[rng.usize(0..alphabet.len())]);
 }
 str::from_utf8(result).unwrap()
}
У этого двухшагового процесса (сначала алфавит, потом строка) есть удобная интерпретация. Чтобы сгенерировать строку, нужно распределение символов.
Можно
брать одно и то же распределение на все миллион итераций. Но есть простой способ всё оживить — сделать случайным
само
распределение. Идею «рандомизировать сами распределения» я отношу к
swarm-тестированию
.
Генерируем распределение для регулярных выражений
Применим те же трюки к генерации регулярного выражения:
выбираем подмножество задействованных возможностей regex;
случайно выбираем размер;
переиспользуем память.
Начнём с первого:
#[derive(Default, Debug)]
struct ReOptions {
 alt: u16, // |
 rep: u16, // *
 any: u16, // .
 lit: u16, // 'a'
 sum: u16,
 alphabet: Vec<u8>,
}
У регулярных выражений есть альтернатива
r1|r2
, повторение
r*
, любой символ
.
и литералы
a
. Вместо того чтобы просто включать или выключать каждую возможность, я назначаю ей вес от 0 до 100 — это чуть более общий подход.
sum
— сумма всех весов. Чтобы выбрать возможность случайно, генерируем число в диапазоне
0..sum
и смотрим, в какой отрезок оно попало.
В чём-то посерьёзнее я бы завёл явные типы для вероятностей и распределений, но для небольшой задачи вполне хватает просто двузначного числа.
Вот как я генерирую
ReOptions
, следя, чтобы у литералов вес всегда был ненулевым, и заодно выбирая для них алфавит:
impl ReOptions {
 fn swarm(&mut self, rng: &mut Rng, alphabet_full: &[u8]) {
 // We _still_ want to enable a few features at a time.
 self.alt = if rng.bool() { 0 } else { rng.u16(0..100) };
 self.rep = if rng.bool() { 0 } else { rng.u16(0..100) };
 self.any = if rng.bool() { 0 } else { rng.u16(0..100) };
 self.lit = rng.u16(1..100);
 self.sum = self.alt + self.rep + self.any + self.lit;
 assert!(self.sum > 0);

 alphabet_swarm(rng, alphabet_full, &mut self.alphabet);
 }
}
Генерируем регулярное выражение
Теперь можно генерировать само регулярное выражение. Удобнее всего делать это рекурсивно. Чтобы обойтись без выделений памяти, через все вызовы передаётся выходной буфер. Чтобы управлять длиной выражения, туда же передаётся параметр
size
, и рекурсивные вызовы, которые ветвятся, делят
size
между потомками:
fn gen_re(
 rng: &mut Rng,
 options: &ReOptions,
 result: &mut Vec<u8>,
) {
 result.clear();
 let size = rng.u8(0..8);
 gen_re_rec(rng, options, result, size);
}

fn gen_re_rec(
 rng: &mut Rng,
 options: &ReOptions,
 result: &mut Vec<u8>,
 size: u8,
) {
 if size == 0 {
 return; // Base case, empty regex.
 }

 // Pick one of the features, according to weights.
 let mut p = rng.u16(0..options.sum);

 if p < options.alt {
 // Alternation distributes the size
 // among the two children.
 let size_left = rng.u8(0..=size - 1);
 let size_right = size - size_left - 1;
 assert!(size == size_left + 1 + size_right);

 result.push(b'(');
 gen_re_rec(rng, options, result, size_left);
 result.extend(b")|(");
 gen_re_rec(rng, options, result, size_right);
 result.push(b')');
 return;
 }
 p -= options.alt;

 if p < options.rep {
 result.push(b'(');
 gen_re_rec(rng, options, result, size - 1);
 result.extend(b")*");
 return;
 }
 p -= options.rep;

 if p < options.any {
 gen_re_rec(rng, options, result, size - 1);
 result.push(b'.');
 return;
 }
 p -= options.any;

 if p < options.lit {
 gen_re_rec(rng, options, result, size - 1);
 let index = rng.usize(0..options.alphabet.len());
 let lit = options.alphabet[index];
 result.push(lit);
 return;
 }

 unreachable!();
}
Цикл поиска
Компиляция регулярных выражений довольно медленная, поэтому разумно прогонять много строк на одной паре скомпилированных выражений. Получается такой код:
fn main() {
 let mut rng = Rng::new();

 let mut options = ReOptions::default();
 let mut text_alphabet: Vec<u8> = vec![];
 let mut text: Vec<u8> = vec![];
 let mut re: Vec<u8> = vec![];

 let mut test_count: u32 = 0;
 for _ in 0..1_000_000 {
 options.swarm(&mut rng, b"abcdef");
 alphabet_swarm(&mut rng, b"abcdefx", &mut text_alphabet);
 gen_re(&mut rng, &options, &mut re);
 let re = str::from_utf8(&re).unwrap();

 let r1 = regex::Regex::new(re).unwrap();
 let r2 = regex_lite::Regex::new(re).unwrap();
 for _ in 0..1000 {
 test_count += 1;
