 gen_string(&mut rng, &text_alphabet, &mut text);
 let m1 = r1.find(text)
 .map_or("not found", |it| it.as_str());
 let m2 = r2.find(text)
 .map_or("not found", |it| it.as_str());
 if m1 != m2 {
 eprintln!("err re={re} text={text} m1={m1} m2={m2}");
 return;
 }
 if test_count % 500_000 == 0 {
 eprintln!("ok re={re} text={text}");
 }
 }
 }
}
